async function handler(req, res) {
  if (req.method !== "POST") return res.status(405).json({ error: "M\xE9todo n\xE3o permitido." });
  try {
    const deck = req.body?.deck;
    const format = String(req.body?.format || "").toLowerCase();
    if (!deck || !Array.isArray(deck.slides) || deck.slides.length === 0) return res.status(400).json({ error: "Apresenta\xE7\xE3o inv\xE1lida." });
    const safeName = String(deck.title || "Slides Aula Clara").replace(/[^a-z0-9áàâãéêíóôõúç\s-]/gi, "").trim().slice(0, 100) || "Slides Aula Clara";
    let buffer;
    let mime;
    if (format === "pptx") {
      buffer = await createEditablePptx(deck);
      mime = "application/vnd.openxmlformats-officedocument.presentationml.presentation";
    } else if (format === "docx") {
      buffer = await createSlidesDocx(deck);
      mime = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
    } else if (format === "pdf") {
      buffer = await createSlidesPdf(deck);
      mime = "application/pdf";
    } else return res.status(400).json({ error: "Formato n\xE3o suportado." });
    res.setHeader("Content-Type", mime);
    res.setHeader("Content-Disposition", `attachment; filename="${safeName}.${format}"`);
    return res.status(200).send(buffer);
  } catch (error) {
    return res.status(500).json({ error: error.message || "Falha ao preparar o arquivo." });
  }
}
